CREATE TABLE `User` (`id` VARCHAR(191) NOT NULL, `zaloOpenId` VARCHAR(191) NOT NULL, `displayName` VARCHAR(191) NULL, `avatarUrl` VARCHAR(191) NULL, `language` VARCHAR(191) NOT NULL DEFAULT 'vi', `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `User_zaloOpenId_key`(`zaloOpenId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `AdminUser` (`id` VARCHAR(191) NOT NULL, `username` VARCHAR(191) NOT NULL, `passwordHash` VARCHAR(191) NOT NULL, `role` VARCHAR(191) NOT NULL DEFAULT 'operator', `enabled` BOOLEAN NOT NULL DEFAULT true, `lastLoginAt` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `AdminUser_username_key`(`username`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `CoinAccount` (`id` VARCHAR(191) NOT NULL, `userId` VARCHAR(191) NOT NULL, `available` INTEGER NOT NULL DEFAULT 0, `frozen` INTEGER NOT NULL DEFAULT 0, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `CoinAccount_userId_key`(`userId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `CoinLedger` (`id` VARCHAR(191) NOT NULL, `accountId` VARCHAR(191) NOT NULL, `type` ENUM('INITIAL_GRANT', 'RESERVATION', 'GENERATION_CHARGE', 'REFUND', 'ADMIN_ADJUSTMENT') NOT NULL, `amount` INTEGER NOT NULL, `availableAfter` INTEGER NOT NULL, `frozenAfter` INTEGER NOT NULL, `idempotencyKey` VARCHAR(191) NOT NULL, `generationId` VARCHAR(191) NULL, `note` VARCHAR(191) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `CoinLedger_idempotencyKey_key`(`idempotencyKey`), INDEX `CoinLedger_accountId_createdAt_idx`(`accountId`, `createdAt`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Template` (`id` VARCHAR(191) NOT NULL, `slug` VARCHAR(191) NOT NULL, `nameVi` VARCHAR(191) NOT NULL, `nameZh` VARCHAR(191) NOT NULL, `prompt` VARCHAR(191) NOT NULL, `coverUrl` VARCHAR(191) NULL, `coinCost` INTEGER NOT NULL DEFAULT 10, `enabled` BOOLEAN NOT NULL DEFAULT true, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `Template_slug_key`(`slug`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Generation` (`id` VARCHAR(191) NOT NULL, `idempotencyKey` VARCHAR(191) NOT NULL, `userId` VARCHAR(191) NOT NULL, `templateId` VARCHAR(191) NOT NULL, `status` ENUM('QUEUED', 'PROCESSING', 'SUCCEEDED', 'FAILED', 'REFUNDED') NOT NULL DEFAULT 'QUEUED', `sourceAssetUrl` VARCHAR(191) NOT NULL, `resultAssetUrl` VARCHAR(191) NULL, `coinCost` INTEGER NOT NULL, `errorCode` VARCHAR(191) NULL, `errorMessage` VARCHAR(191) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `Generation_idempotencyKey_key`(`idempotencyKey`), INDEX `Generation_userId_createdAt_idx`(`userId`, `createdAt`), INDEX `Generation_status_createdAt_idx`(`status`, `createdAt`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Asset` (`id` VARCHAR(191) NOT NULL, `userId` VARCHAR(191) NOT NULL, `kind` VARCHAR(191) NOT NULL, `storageKey` VARCHAR(191) NOT NULL, `publicUrl` VARCHAR(191) NOT NULL, `mimeType` VARCHAR(191) NOT NULL, `byteSize` INTEGER NOT NULL, `expiresAt` DATETIME(3) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `Asset_storageKey_key`(`storageKey`), INDEX `Asset_userId_kind_createdAt_idx`(`userId`, `kind`, `createdAt`), INDEX `Asset_expiresAt_idx`(`expiresAt`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `ApiKey` (`id` VARCHAR(191) NOT NULL, `label` VARCHAR(191) NOT NULL, `encryptedValue` VARCHAR(191) NOT NULL, `priority` INTEGER NOT NULL DEFAULT 100, `status` ENUM('ACTIVE', 'PAUSED', 'EXHAUSTED', 'INVALID') NOT NULL DEFAULT 'ACTIVE', `failureCount` INTEGER NOT NULL DEFAULT 0, `lastUsedAt` DATETIME(3) NULL, `pausedUntil` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, INDEX `ApiKey_status_priority_idx`(`status`, `priority`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `CoinAccount` ADD CONSTRAINT `CoinAccount_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `CoinLedger` ADD CONSTRAINT `CoinLedger_accountId_fkey` FOREIGN KEY (`accountId`) REFERENCES `CoinAccount`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `CoinLedger` ADD CONSTRAINT `CoinLedger_generationId_fkey` FOREIGN KEY (`generationId`) REFERENCES `Generation`(`id`) ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE `Generation` ADD CONSTRAINT `Generation_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `Generation` ADD CONSTRAINT `Generation_templateId_fkey` FOREIGN KEY (`templateId`) REFERENCES `Template`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `Asset` ADD CONSTRAINT `Asset_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
